object JsonTokenizer {
  import JsonValue._

  def render(value: JsonValue, pretty: Boolean): String = {
    val indentStep = 2

    def escape(s: String): String =
      s.flatMap {
        case '"' => "\\\""
        case '\\' => "\\\\"
        case '\b' => "\\b"
        case '\f' => "\\f"
        case '\n' => "\\n"
        case '\r' => "\\r"
        case '\t' => "\\t"
        case c if c.isControl => f"\\u${c.toInt}%04x"
        case c => c.toString
      }

    def pad(n: Int): String = " " * n

    def loop(v: JsonValue, indent: Int): String = v match {
      case JsonNull => "null"
      case JsonBool(b) => b.toString
      case JsonNumber(n) => n.toString
      case JsonString(s) => s"\"${escape(s)}\""
      case JsonArray(items) if items.isEmpty => "[]"
      case JsonArray(items) =>
        if (!pretty) items.map(loop(_, indent)).mkString("[", ",", "]")
        else {
          val inner = items.map(i => pad(indent + indentStep) + loop(i, indent + indentStep)).mkString(",\n")
          s"[\n$inner\n${pad(indent)}]"
        }
      case JsonObject(fields) if fields.isEmpty => "{}"
      case JsonObject(fields) =>
        val renderedFields = fields.toVector.sortBy(_._1).map { case (k, vv) =>
          val key = s"\"${escape(k)}\""
          if (!pretty) s"$key:${loop(vv, indent)}" else s"${pad(indent + indentStep)}$key: ${loop(vv, indent + indentStep)}"
        }

        if (!pretty) renderedFields.mkString("{", ",", "}")
        else {
          val inner = renderedFields.mkString(",\n")
          s"{\n$inner\n${pad(indent)}}"
        }
    }

    loop(value, indent = 0)
  }
}

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word0: String): Option[String] = {
    val stripped =
      if (!stripPunctuation) word0
      else word0.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) None
    else {
      val maybeTruncated = maxLength match {
        case Some(m) if normalized.length > m => normalized.take(m)
        case _ => normalized
      }
      Option(maybeTruncated).filter(_.nonEmpty)
    }
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").toList.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toList

    val (_, result) = words.foldLeft((0, List.empty[(String, Int, Int)])) { case ((currentPos, acc), word) =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      val updatedAcc = processToken(word) match {
        case Some(processed) => acc :+ ((processed, start, end))
        case None => acc
      }

      (end, updatedAcc)
    }

    result
  }

  def countTokens(text: String): Int = tokenize(text).length
}

